
from langchain_core.messages import ToolMessage
from langchain_core.runnables import RunnableConfig

from packages.agent_graph.state import AgentState
from packages.security.gateway import gateway
from packages.security.policy import Denied
from packages.security.taint import taint_tracker


async def secure_tool_node(
    state: AgentState,
    config: RunnableConfig,
) -> dict:

    # Get tool calls generated by the LLM.
    last_message = state["messages"][-1]
    tool_calls = getattr(last_message, "tool_calls", [])

    configurable = config.get("configurable", {})

    # These values must come from trusted application configuration.
    context_id = configurable.get("thread_id", "default-session")
    principal = configurable.get("user_id", "local-user")

    tool_messages = []

    # Execute sequentially for predictable rate limiting and auditing.
    for tool_call in tool_calls:

        tool_name = tool_call["name"]
        tool_args = tool_call["args"]
        tool_call_id = tool_call["id"]

        try:
            result = await gateway.execute(
                tool_name,
                tool_args,
                principal=principal,
                granted_scopes=(),
                tainted=taint_tracker.is_tainted(context_id),
                context_id=context_id,
            )

            content = str(result)

        except Denied as exc:
            content = f"Tool blocked by security policy: {exc}"

        except Exception as exc:
            content = (
                "Tool execution failed or its status is uncertain. "
                "Do not automatically retry this operation. "
                f"Error: {type(exc).__name__}: {exc}"
            )

        tool_messages.append(
            ToolMessage(
                content=content,
                tool_call_id=tool_call_id,
                name=tool_name,
            )
        )

    return {"messages": tool_messages}
